import pyomo.environ as pyo

DATA = {
    "categories": ["teacher", "rent", "textbook", "misc"],
    "cost": {
        "teacher": 0.3,
        "rent": 0.2,
        "textbook": 0.4,
        "misc": 0.1,
    },
    "lb": {
        "teacher": 50000,
        "rent": 10000,
        "textbook": 5000,
        "misc": 5000,
    },
    "ub": {
        "teacher": 80000,
        "rent": 20000,
        "textbook": 10000,
        "misc": 7000,
    },
    # Total budget must be supplied by the caller; choose a feasible default.
    "budget": 100000,
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.C = pyo.Set(initialize=d["categories"])

    def _lb(m, i):
        return d["lb"][i]

    def _ub(m, i):
        return d["ub"][i]

    # x[i]: dollars allocated to category i (whole dollars)
    model.x = pyo.Var(
        model.C,
        domain=pyo.NonNegativeIntegers,
        bounds=lambda m, i: (d["lb"][i], d["ub"][i]),
    )

    # Objective: minimise total resource consumption
    def rule_obj(m):
        return sum(d["cost"][i] * m.x[i] for i in model.C)

    model.obj = pyo.Objective(rule=rule_obj, sense=pyo.minimize)

    # Lower-bound constraints (explicit, one rule per atomic sentence intent)
    def rule_lb(m, i):
        return m.x[i] >= d["lb"][i]

    model.lower_bound = pyo.Constraint(model.C, rule=rule_lb)

    # Upper-bound constraints
    def rule_ub(m, i):
        return m.x[i] <= d["ub"][i]

    model.upper_bound = pyo.Constraint(model.C, rule=rule_ub)

    # Total allocation equals the available budget
    def rule_budget(m):
        return sum(m.x[i] for i in model.C) == d["budget"]

    model.budget = pyo.Constraint(rule=rule_budget)

    return model


